import{_ as a,o as e,c as r,aO as n}from"./chunks/framework.BFrk9dwu.js";const c=JSON.parse('{"title":"提示词","description":"","frontmatter":{"date":"2026-11-27T11:05:06.000Z","title":"提示词","sidebarSort":1,"categories":["ai"],"permalink":"/pages/1f621a"},"headers":[],"relativePath":"ai/01.基础知识/index.md","filePath":"ai/01.基础知识/index.md","lastUpdated":1795773654000}'),s={name:"ai/01.基础知识/index.md"};function d(i,t,l,o,h,p){return e(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="提示词" tabindex="-1">提示词 <a class="header-anchor" href="#提示词" aria-label="Permalink to &quot;提示词&quot;">​</a></h1><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><p>提示词（prompt）不是「咒语」，而是<strong>一份写给不认识你的执行者的任务说明</strong>。它至少要说清三件事：你是什么角色、要做什么、做完长什么样。</p><p>好提示词和差提示词的差距，通常大于换一个模型的差距。</p><h2 id="有什么用" tabindex="-1">有什么用 <a class="header-anchor" href="#有什么用" aria-label="Permalink to &quot;有什么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>不写清会怎样</th><th>写清后</th></tr></thead><tbody><tr><td>输出一大段，还得自己删</td><td>直接可用，返工一次以内</td></tr><tr><td>每次格式都不一样</td><td>结构稳定，能直接粘进文档或代码</td></tr><tr><td>说「不够好」但改不动</td><td>知道改哪一段约束</td></tr></tbody></table><h2 id="提示词的四件套" tabindex="-1">提示词的四件套 <a class="header-anchor" href="#提示词的四件套" aria-label="Permalink to &quot;提示词的四件套&quot;">​</a></h2><p>按这个顺序写，缺一块就有返工风险：</p><ol><li><strong>角色</strong>：让它站在谁的位置说话（三年经验的运维、严格的技术编辑）</li><li><strong>任务</strong>：一句话说清产出物是什么（一份 300 字公告 / 一个 JSON / 一次代码审查）</li><li><strong>约束</strong>：字数、格式、必须包含、禁止出现、语气</li><li><strong>示例</strong>：给一个「像这样」的样本，或给反例</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是负责对外沟通的技术编辑。（角色）</span></span>\n<span class="line"><span>把下面这段内部说明改写成给客户看的故障公告，200 字以内。（任务）</span></span>\n<span class="line"><span>不要出现内部系统代号，不要承诺恢复时间，第一段先说明影响范围。（约束）</span></span>\n<span class="line"><span>参考写法：先一句现状，再一句我们正在做什么，最后一句何时同步进展。（示例）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="少样本示例比形容词管用" tabindex="-1">少样本示例比形容词管用 <a class="header-anchor" href="#少样本示例比形容词管用" aria-label="Permalink to &quot;少样本示例比形容词管用&quot;">​</a></h2><p>说「风格活泼一点」，十个人有十个理解；贴一条真实的好文案，理解立刻收敛。</p><table tabindex="0"><thead><tr><th>手段</th><th>什么时候用</th></tr></thead><tbody><tr><td>单示例</td><td>格式要求明确，如「按这条记录的结构输出」</td></tr><tr><td>多示例（2–3 条）</td><td>需要抓住某种语气、分类边界</td></tr><tr><td>反例</td><td>常见错误反复出现时，直接把错的样子贴出来</td></tr></tbody></table><p>示例不是越多越好，超过五条容易挤占上下文、也让模型死抠表面格式。</p><h2 id="让输出结构化" tabindex="-1">让输出结构化 <a class="header-anchor" href="#让输出结构化" aria-label="Permalink to &quot;让输出结构化&quot;">​</a></h2><p>要交给代码处理，就要求 JSON，并给出字段说明和类型：</p><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>title</td><td>string</td><td>不超过 20 字</td></tr><tr><td>tags</td><td>string[]</td><td>2–4 个</td></tr><tr><td>summary</td><td>string</td><td>一句话概括</td></tr></tbody></table><p>配一句「只输出 JSON，不要解释」，再在代码里做容错解析：去掉可能的 ```json 包裹、捕获解析异常后重试一次。</p><h2 id="分步思考和追问" tabindex="-1">分步思考和追问 <a class="header-anchor" href="#分步思考和追问" aria-label="Permalink to &quot;分步思考和追问&quot;">​</a></h2><p>复杂任务别指望一次成型，用两轮：</p><ol><li>第一轮让它<strong>列步骤或提纲</strong>，你先判断思路对不对</li><li>第二轮再让它按提纲填内容</li></ol><p>思路错了就重来，比让它写完三千字再改省力得多。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p><strong>现象：让它「写得专业一点」，结果堆满形容词。</strong> 原因：抽象形容词没有可执行标准。 解法：换成可检验的约束，如「不用形容词，每段至少一个具体数字或例子」。</p><p><strong>现象：要求「不要编造」，它还是编。</strong> 原因：否定式约束在长文本里容易失效。 解法：改成肯定式流程——「先列出你确定的部分，不确定的标注『待核实』，再给表述」。</p><p><strong>现象：一改要求，前面好的部分也跟着变了。</strong> 原因：整段重写，上下文一起漂移。 解法：分段迭代，锁定已通过的部分，只让它改指定段落。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><ol><li>提示词是任务说明，不是咒语；四件套顺序写：角色、任务、约束、示例</li><li>抽象形容词换成可检验的标准，产出立刻稳定</li><li>要给代码用就输出 JSON，并加「只输出 JSON」+ 容错解析</li><li>复杂任务拆两轮：先提纲，后填充</li><li>约束尽量用肯定式流程，少用「不要……」这种否定式</li><li>有效的提示词存成文件，版本化管理，别只活在聊天框里</li></ol>',28)])])}const u=a(s,[["render",d]]);export{c as __pageData,u as default};
